using System.ComponentModel;
using System.Net;
using System.Text;
using System.Text.Json;
using System.Text.RegularExpressions;
using Microsoft.Extensions.AI;

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------
string modelName = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";
string? apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY");
if (string.IsNullOrWhiteSpace(apiKey))
{
    Console.Error.WriteLine("Set the OPENAI_API_KEY environment variable before running.");
    return 1;
}

// ---------------------------------------------------------------------------
// Tool implementations
// ---------------------------------------------------------------------------
var notebook = new Notebook();
var webSearcher = new WebSearcher();

// ---------------------------------------------------------------------------
// Build the chat client with automatic tool invocation
// ---------------------------------------------------------------------------
IChatClient client = new ChatClientBuilder(
        new OpenAI.OpenAIClient(apiKey).GetChatClient(modelName).AsIChatClient())
    .UseFunctionInvocation()
    .Build();

var tools = new AITool[]
{
    AIFunctionFactory.Create(webSearcher.Search),
    AIFunctionFactory.Create(notebook.AddNote),
    AIFunctionFactory.Create(notebook.GetNotes),
};

// ---------------------------------------------------------------------------
// Prompt the user for a research topic
// ---------------------------------------------------------------------------
Console.Write("Enter a research topic: ");
string? topic = Console.ReadLine();
if (string.IsNullOrWhiteSpace(topic))
{
    Console.Error.WriteLine("No topic provided.");
    return 1;
}

Console.WriteLine($"\n🔍 Researching: {topic}\n");

// ---------------------------------------------------------------------------
// Agent loop
// ---------------------------------------------------------------------------
var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your goal is to research the topic the user gives you
        and produce a well-structured summary.

        You have access to these tools:
        1. **Search** – search the web for information. Call it multiple times with
           different queries to get broad coverage.
        2. **AddNote** – save an important finding so you can reference it later.
        3. **GetNotes** – retrieve all saved notes.

        Workflow:
        - Search for the topic using several varied queries (at least 3).
        - Save the most important facts as notes.
        - After gathering enough information, retrieve your notes and write a final
          summary in Markdown with sections, bullet points, and sources where possible.
        - When you are done, output the summary directly to the user.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a summary:\n\n{topic}"),
};

var options = new ChatOptions { Tools = [.. tools] };

ChatResponse response = await client.GetResponseAsync(messages, options);
Console.WriteLine(response.Text);

return 0;

// ===========================================================================
// Web search tool
// ===========================================================================
partial class WebSearcher
{
    private static readonly HttpClient Http = new()
    {
        DefaultRequestHeaders =
        {
            { "User-Agent", "ResearchAgent/1.0" },
            { "Accept", "text/html" },
        },
        Timeout = TimeSpan.FromSeconds(15),
    };

    [Description("Search the web for information on a query. Returns a list of result snippets.")]
    public async Task<string> Search(
        [Description("The search query string")] string query)
    {
        Console.WriteLine($"  🌐 Searching: {query}");

        try
        {
            // Use DuckDuckGo HTML-only endpoint (no API key required).
            string encoded = WebUtility.UrlEncode(query);
            string url = $"https://html.duckduckgo.com/html/?q={encoded}";
            string html = await Http.GetStringAsync(url);

            var results = ParseSearchResults(html);
            if (results.Count == 0)
                return "No results found.";

            var sb = new StringBuilder();
            foreach (var (title, snippet) in results.Take(6))
                sb.AppendLine($"- **{title}**: {snippet}");

            return sb.ToString();
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    private static List<(string Title, string Snippet)> ParseSearchResults(string html)
    {
        var results = new List<(string, string)>();

        // Extract result blocks from DuckDuckGo HTML response.
        var snippetMatches = SnippetRegex().Matches(html);
        var titleMatches = TitleRegex().Matches(html);

        int count = Math.Min(titleMatches.Count, snippetMatches.Count);
        for (int i = 0; i < count && i < 8; i++)
        {
            string title = StripHtml(titleMatches[i].Groups[1].Value).Trim();
            string snippet = StripHtml(snippetMatches[i].Groups[1].Value).Trim();
            if (!string.IsNullOrWhiteSpace(title) && !string.IsNullOrWhiteSpace(snippet))
                results.Add((title, snippet));
        }

        return results;
    }

    private static string StripHtml(string html)
    {
        string decoded = WebUtility.HtmlDecode(html);
        return HtmlTagRegex().Replace(decoded, " ").Trim();
    }

    [GeneratedRegex(@"<a[^>]+class=""result__a""[^>]*>(.*?)</a>", RegexOptions.Singleline)]
    private static partial Regex TitleRegex();

    [GeneratedRegex(@"<a[^>]+class=""result__snippet""[^>]*>(.*?)</a>", RegexOptions.Singleline)]
    private static partial Regex SnippetRegex();

    [GeneratedRegex(@"<[^>]+>")]
    private static partial Regex HtmlTagRegex();
}

// ===========================================================================
// Note-taking tool
// ===========================================================================
class Notebook
{
    private readonly List<string> _notes = [];

    [Description("Save an important research finding as a note.")]
    public string AddNote(
        [Description("The note text to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  📝 Note saved ({_notes.Count} total)");
        return $"Note saved. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieve all saved research notes.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        var sb = new StringBuilder();
        for (int i = 0; i < _notes.Count; i++)
            sb.AppendLine($"{i + 1}. {_notes[i]}");

        Console.WriteLine($"  📖 Retrieved {_notes.Count} note(s)");
        return sb.ToString();
    }
}

